import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        HZSShufflesCards solver = new HZSShufflesCards();
        solver.solve(1, in, out);
        out.close();
    }

    static class HZSShufflesCards {
        final long MOD = 998244353L;
        int n, m;
        long[] fact, invFact;

        void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();

            fact = new long[n + m + 1];
            invFact = new long[n + m + 1];
            fact[0] = 1;
            for (int i = 1; i <= n + m; i++) {
                fact[i] = fact[i - 1] * i % MOD;
            }

            invFact[n + m] = inv(fact[n + m]);
            for (int i = n + m; i >= 1; i--) {
                invFact[i - 1] = invFact[i] * i % MOD;
            }

            long phaseSize = 1;
            long p = 1;
            for (int i = 0; ; i++) {
                p = p * (n - i) % MOD * smallInv(n + m - i) % MOD;
                phaseSize = add(phaseSize, p);
                if (p == 0) break;
            }

            long answer = 0;
            for (int k = 1; k <= n; k++) {
                long numPhases = (m + k) % MOD * smallInv(k) % MOD;
                long e = numPhases * phaseSize % MOD;
                long term = ncr(n, k) * e % MOD;

                if ((k & 1) == 1) {
                    answer = add(answer, term);
                } else {
                    answer = subtract(answer, term);
                }
            }

            out.println(answer);
        }

        long smallInv(int x) {
            return inv(x);
        }

        long inv(long a) {
            long g = MOD, x = 0, y = 1;
            long r = a;
            while (r != 0) {
                long q = g / r;
                g %= r;
                long tmp = g;
                g = r;
                r = tmp;
                x -= q * y;
                tmp = x;
                x = y;
                y = tmp;
            }
            if (g != 1) throw new AssertionError();
            x %= MOD;
            if (x < 0) x += MOD;
            return x;
        }

        long ncr(int n, int r) {
            if (r < 0 || r > n) return 0;
            return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
        }

        long add(long a, long b) {
            long v = a + b;
            return v < MOD ? v : v - MOD;
        }

        long subtract(long a, long b) {
            long v = a - b;
            return v < 0 ? v + MOD : v;
        }
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
